class Solution {
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public int numIslands(char[][] grid) {
        int m = grid.length, n = grid[0].length, count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '1') {
                    continue;
                }
                count++;
                grid[i][j] = '0';
                Deque<int[]> q = new ArrayDeque<>();
                q.offer(new int[]{i, j});
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    for (int[] d : DIRS) {
                        int a = cur[0] + d[0], b = cur[1] + d[1];
                        if (a >= 0 && a < m && b >= 0 && b < n && grid[a][b] == '1') {
                            grid[a][b] = '0';                   // 入队时就做记号
                            q.offer(new int[]{a, b});
                        }
                    }
                }
            }
        }
        return count;
    }
}

